// [MEDIUM_PRIORITY] VALIDATION: Long conversion safe
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.emotionimport timber.log.Timberimport com.roshan.persona.voice.capture.AudioCapturePipelineimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContextimport kotlin.math.absimport kotlin.math.sqrt/** * NOUS — Speech Emotion Recognizer (§16 v2 Fix #1). * * Detects the user's emotional state from their voice — runs in **parallel** * with STT so it adds zero latency to the conversation. The result is fed * to the Brain (Module 2) as `[USER_EMOTION=ANGRY]` in the context, which * influences both the response content and the TTS emotion NOUS uses to * reply (§16 Brain Integration). * * ## Two-tier architecture (mirrors Step 5.7/5.9 pattern) * * ``` * Tier 1: WavLM/HuBERT SER (primary)  — 45 MB ONNX, ~85 % accuracy *   Self-supervised speech model fine-tuned for SER. Outputs softmax *   probabilities over the 7 emotion classes. * * Tier 2: Heuristic fallback (always available) *   Combines 3 acoustic signals: *     - Pitch contour  (high + variable → ANGRY/HAPPY/SURPRISED) *     - Energy         (loud → ANGRY/HAPPY; quiet → SAD/FEARFUL) *     - Speaking rate  (fast → ANGRY/HAPPY; slow → SAD) *   ~55 % accuracy — good enough to avoid responding HAPPY to a SAD user. * ``` * * ## Why parallel to STT (§16) * * STT extracts *what* the user said; SER extracts *how* they said it. * Both consume the same audio stream. Running them in parallel on separate * dispatchers means: *  - STT latency is unaffected (~300 ms cloud, ~1 s offline). *  - SER latency is hidden behind STT (Brain waits for both, then proceeds). *  - Net perceived latency = max(STT, SER) ≈ STT latency (SER is faster). * * ## Brain integration (§16 Brain Integration) * * The Brain receives the user emotion and: *  1. Injects `[USER_EMOTION=ANGRY]` into the LLM prompt so the LLM knows *     to respond concisely and non-defensively. *  2. Overrides the TTS emotion — NOUS responds CALM to an ANGRY user *     (de-escalation), CALM to a SAD user (reassurance), HAPPY to a HAPPY *     user (mirroring). * * Use [UserEmotion.toNousResponseEmotion] for the mapping. * * ## Testability * * [WavlmSerBackend] is an interface — tests inject a fake. The heuristic * path is fully testable in pure Kotlin (no native deps). * * @see <a href="docs/strategy/module-5-strategy-v2.md">§16 Speech Emotion Recognition — v2 Fix #1</a> */class SpeechEmotionRecognizer(    private val wavlmBackend: WavlmSerBackend?,    private val config: SerConfig = SerConfig(),    private val inferenceDispatcher: CoroutineDispatcher,) {    /**     * Detect emotion from speech audio.     *     * @param audio 16 kHz, 16-bit mono PCM. Must be at least     *              [SerConfig.minAudioSeconds] long for reliable detection.     * @return the detected [UserEmotion], or [UserEmotion.UNKNOWN] if the     *         audio is too short or detection fails.     */    suspend fun recognize(audio: ShortArray): UserEmotion = withContext(inferenceDispatcher) {        if (audio.size < config.minAudioSeconds * AudioCapturePipeline.SAMPLE_RATE) {            Timber.tag(TAG).w("Audio too short (${audio.size} samples) — returning UNKNOWN.")            return@withContext UserEmotion.UNKNOWN        }        // 1. Try WavLM SER (primary).        if (wavlmBackend != null && wavlmBackend.isReady) {            val scores = runCatching { wavlmBackend.classify(audio) }                .onFailure { Timber.tag(TAG).w("WavLM SER failed, falling back to heuristic.", it) }                .getOrNull()            if (scores != null && scores.isNotEmpty()) {                val normalized = normalizeScores(scores)                return@withContext UserEmotion.fromScores(                    scores = normalized,                    source = EmotionDetectionSource.WAVLM,                )            }        }        // 2. Fall back to heuristic (always available).        val heuristicScores = runHeuristic(audio)        UserEmotion.fromScores(            scores = heuristicScores,            source = EmotionDetectionSource.HEURISTIC,        )    }    // ──────────────────────────────────────────────────────────────────────    // Heuristic emotion detection (pure functions for testability).    // ──────────────────────────────────────────────────────────────────────    /**     * Heuristic emotion classification from acoustic features.     *     * Computes pitch variability, RMS energy, and speaking rate, then maps     * them to emotion scores via simple thresholds. ~55 % accuracy — good     * enough to avoid jarring mismatches (responding HAPPY to a SAD user).     */    internal fun runHeuristic(audio: ShortArray): Map<UserEmotionType, Float> {        val pitchStats = computePitchStats(audio)        val energy = computeRmsEnergy(audio)        val rate = computeSpeakingRate(audio)        // Normalize to 0-1 ranges.        val energyNorm = (energy / 5000f).coerceIn(0f, 1f)        val pitchVarNorm = (pitchStats.variability / 100f).coerceIn(0f, 1f)        val rateNorm = (rate / 5f).coerceIn(0f, 1f)        // Score each emotion based on acoustic profile.        // These weights are heuristic — derived from speech emotion research        // (low pitch variance + low energy + slow rate → SAD, etc.).        val scores = mutableMapOf<UserEmotionType, Float>()        scores[UserEmotionType.NEUTRAL] = 0.4f * (1 - pitchVarNorm) * (1 - abs(energyNorm - 0.5f) * 2)        scores[UserEmotionType.HAPPY] = 0.3f * energyNorm * pitchVarNorm + 0.2f * rateNorm        scores[UserEmotionType.SAD] = 0.4f * (1 - energyNorm) * (1 - rateNorm) + 0.2f * (1 - pitchVarNorm)        scores[UserEmotionType.ANGRY] = 0.4f * energyNorm * pitchVarNorm + 0.3f * rateNorm        scores[UserEmotionType.FEARFUL] = 0.3f * pitchVarNorm * (1 - energyNorm) + 0.2f * (1 - rateNorm)        scores[UserEmotionType.SURPRISED] = 0.3f * pitchVarNorm * rateNorm + 0.2f * energyNorm        scores[UserEmotionType.DISGUSTED] = 0.2f * (1 - rateNorm) * (1 - pitchVarNorm) + 0.1f * (1 - energyNorm)        return normalizeScores(scores)    }    /**     * Normalize a score map so all values sum to 1.0 (softmax-like).     *     * If all values are 0, returns uniform distribution.     */    internal fun normalizeScores(scores: Map<UserEmotionType, Float>): Map<UserEmotionType, Float> {        val total = scores.values.sum()        if (total <= 0f) {            // Uniform fallback — every emotion gets equal probability.            val uniform = 1f / scores.size            return scores.keys.associateWith { uniform }        }        return scores.mapValues { it.value / total }    }    /**     * Compute pitch statistics over the audio.     *     * Returns mean pitch (Hz) + variability (stddev in Hz). Simplified v1:     * uses zero-crossing rate as a pitch proxy (real impl would use YIN).     */    internal fun computePitchStats(audio: ShortArray): PitchStats {        val frameSize = AudioCapturePipeline.SAMPLE_RATE / 10  // 100 ms frames        val numFrames = audio.size / frameSize        if (numFrames == 0) return PitchStats(meanHz = 0f, variability = 0f)        val framePitches = FloatArray(numFrames)        for (frameIdx in 0 until numFrames) {            val start = frameIdx * frameSize            var zeroCrossings = 0            for (i in start until (start + frameSize - 1)) {                if ((audio[i] < 0) != (audio[i + 1] < 0)) zeroCrossings++            }            // ZCR × sampleRate / 2 / frameSize ≈ fundamental frequency.            framePitches[frameIdx] = (zeroCrossings * AudioCapturePipeline.SAMPLE_RATE.toFloat()) / (2 * frameSize)        }        val mean = framePitches.average().toFloat()        val variance = framePitches.fold(0.0) { acc, p -> acc + (p - mean) * (p - mean) } / numFrames        val stddev = sqrt(variance).toFloat()        return PitchStats(meanHz = mean, variability = stddev)    }    /** Compute RMS energy of the audio (raw 16-bit sample units). */    internal fun computeRmsEnergy(audio: ShortArray): Float {        if (audio.isEmpty()) return 0f        var sumSq = 0L        for (s in audio) sumSq += s.toLong() * s.toLong()        return sqrt(sumSq.toDouble() / audio.size).toFloat()    }    /**     * Estimate speaking rate (syllables per second) via energy envelope peaks.     *     * Simplified: count the number of times the energy envelope crosses     * above the mean — each crossing ≈ one syllable onset.     */    internal fun computeSpeakingRate(audio: ShortArray): Float {        val frameSize = AudioCapturePipeline.SAMPLE_RATE / 100  // 10 ms frames        val numFrames = audio.size / frameSize        if (numFrames < 2) return 0f        val energies = FloatArray(numFrames)        for (frameIdx in 0 until numFrames) {            val start = frameIdx * frameSize            var sumSq = 0L            for (i in start until (start + frameSize)) {                sumSq += audio[i].toLong() * audio[i]            }            energies[frameIdx] = sqrt(sumSq.toDouble() / frameSize).toFloat()        }        val meanEnergy = energies.average().toFloat()        var crossings = 0        var aboveMean = false        for (e in energies) {            val nowAbove = e > meanEnergy            if (nowAbove && !aboveMean) crossings++            aboveMean = nowAbove        }        val durationSec = numFrames * frameSize.toFloat() / AudioCapturePipeline.SAMPLE_RATE        return if (durationSec > 0) crossings / durationSec else 0f    }    // ──────────────────────────────────────────────────────────────────────    /** Pitch statistics for the audio. */    data class PitchStats(val meanHz: Float, val variability: Float)    private companion object {        private const val TAG = "SpeechEmotionRecognizer"    }}// ──────────────────────────────────────────────────────────────────────────/** * ONNX Runtime backend for WavLM/HuBERT SER. * * Real implementation lives in :native:wavlm (ships Year 2 per §24). * Tests inject a fake to verify the recognizer pipeline without needing * ONNX Runtime. * * The model takes raw 16 kHz audio and outputs softmax probabilities over * the 7 emotion classes (NEUTRAL, HAPPY, SAD, ANGRY, FEARFUL, SURPRISED, * DISGUSTED). */interface WavlmSerBackend {    /**     * Classify emotion from raw audio.     *     * @param audio 16 kHz, 16-bit mono PCM.     * @return map of emotion → softmax probability (all values sum to ~1.0).     * @throws Throwable if inference fails (caller catches and falls back).     */    fun classify(audio: ShortArray): Map<UserEmotionType, Float>    /** Whether the ONNX model is loaded and ready. */    val isReady: Boolean    /** Release ONNX resources. */    fun release()}